<?php $p=gw_product(get_queried_object_id());if (!$p) { global $wp_query;$wp_query->set_404();status_header(404);get_template_part('404');return; }get_header();$v=gw_variant($p,sanitize_text_field(wp_unslash($_GET['variant']??''))); ?>
<article class="container product-detail section" data-detail-product="<?php echo (int)$p['id']; ?>"><div class="detail-art"><?php gw_product_media($p,$v,true); ?></div><div class="detail-intro"><p class="eyebrow"><a href="<?php echo esc_url(gw_link('categories/'.$p['category'])); ?>"><?php echo esc_html(gw_categories()[$p['category']]); ?></a> · <?php echo esc_html($p['brand']); ?></p><h1><?php echo esc_html($p['name']); ?></h1><p class="lede"><?php echo esc_html($p['summary']); ?></p><form method="get" class="variant-form"><label>Checked pack or model<select name="variant"><?php foreach ($p['variants'] as $var) { echo '<option value="'.esc_attr($var['label']).'" '.selected($v['label'],$var['label'],false).'>'.esc_html($var['label'].' · '.gw_price($var['price'])).'</option>'; } ?></select></label><button class="small-button" type="submit">Use this variant</button></form><p class="detail-price"><?php echo esc_html(gw_price($v['price'])); ?></p><p><?php echo esc_html($v['availability']); ?></p><p class="fine"><?php echo esc_html($v['priceBasis']); ?>. Checked <?php echo esc_html($p['checked']); ?>. Price and stock can change.</p><div class="actions"><a class="button" data-retailer href="<?php echo esc_url($v['source']); ?>" rel="noopener external"><?php echo esc_html(gw_purchase_label($v['source'])); ?> <span aria-hidden="true">↗</span></a><button class="button secondary js-only" data-save="<?php echo (int)$p['id']; ?>" aria-pressed="false">Save product</button><button class="small-button js-only" data-compare="<?php echo (int)$p['id']; ?>" data-variant="<?php echo esc_attr($v['label']); ?>">Add to compare</button></div><p class="fine">You leave Glowwise to buy. We do not sell this product or receive a commission from this link.</p></div>
<div class="product-review"><div><p class="eyebrow">The useful distinction</p><h2>Why it’s in the edit.</h2><p><?php echo esc_html($p['strength']); ?></p></div><div><p class="eyebrow">The other side</p><h2>Before you choose.</h2><p><?php echo esc_html($p['limitation']); ?></p></div></div>
<section class="detail-facts"><h2>What the source says.</h2><p>Label and manufacturer information, not independent performance testing.</p><dl class="fact-list"><?php foreach ($p['attributes'] as $k=>$value) { echo '<div><dt>'.esc_html(ucwords(str_replace('-',' ',$k))).'</dt><dd>'.esc_html($value==='unknown'?'Not verified':$value).'</dd></div>'; } ?></dl><div class="prose"><?php echo apply_filters('the_content',get_post_field('post_content',$p['id'])); ?></div><h3>Follow the research.</h3><ul class="source-list"><li><a href="<?php echo esc_url($p['source']); ?>" rel="noopener external">Manufacturer product information ↗</a></li><?php foreach ($p['sources'] as $u) { echo '<li><a href="'.esc_url($u).'" rel="noopener external">Additional reference ↗</a></li>'; } ?></ul><a class="text-link" href="<?php echo esc_url(add_query_arg('page-url',$p['url'],gw_link('corrections'))); ?>">Something changed? Send a correction ↗</a></section></article>
<section class="container section"><div class="section-heading"><h2>A useful comparison.</h2><a class="text-link" href="<?php echo esc_url(add_query_arg('type',$p['type'],gw_link('explore'))); ?>">All <?php echo esc_html(strtolower(gw_types()[$p['type']])); ?>s ↗</a></div><div class="product-grid"><?php $n=0;foreach (gw_catalog() as $other) { if ($other['id']!==$p['id'] && $other['type']===$p['type']) { gw_product_card($other);if (++$n===3) { break; } } } ?></div></section><?php get_footer(); ?>
